<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import TitleCard from '@/shared/ui/TitleCard.vue';
import BasePoster from '@/shared/ui/BasePoster.vue';
import BaseSkeleton from '@/shared/ui/BaseSkeleton.vue';
import { searchTitles } from '@/entities/catalog/catalog.api';
import { fetchGenres } from '@/entities/genre/genre.api';
import { useIntersection } from '@/shared/composables/useIntersection';
import { MIN_QUERY_LENGTH, SEARCH_DEBOUNCE_MS, PAGE_SIZE } from '@/shared/config/env';
import type { Genre, SortKey, TitleListItem } from '@/shared/api/types';

const route = useRoute();
const router = useRouter();

const SORTS: { key: SortKey; label: string }[] = [
  { key: 'relevance', label: 'Релевантність' },
  { key: 'translation_date', label: 'Нові' },
  { key: 'views', label: 'Популярні' },
  { key: 'rating', label: 'Рейтинг' },
  { key: 'original_date', label: 'Реліз' },
];

const q = ref(typeof route.query.q === 'string' ? route.query.q : '');
const selectedGenres = ref<number[]>([]);
const sort = ref<SortKey>('relevance');
const genres = ref<Genre[]>([]);

const items = ref<TitleListItem[]>([]);
const loading = ref(false);
const done = ref(false);
const error = ref<string | null>(null);
const tooShort = ref(false);
const sentinel = ref<Element | null>(null);

let cursor: string | undefined;
let generation = 0;
let controller: AbortController | null = null;
let debounceTimer: ReturnType<typeof setTimeout> | undefined;

async function runSearch(reset: boolean): Promise<void> {
  const trimmed = q.value.trim();
  tooShort.value = trimmed.length > 0 && trimmed.length < MIN_QUERY_LENGTH;
  if (tooShort.value) {
    items.value = [];
    done.value = true;
    loading.value = false;
    return;
  }

  if (reset) {
    generation++;
    cursor = undefined;
    items.value = [];
    done.value = false;
    error.value = null;
    if (loading.value) {
      controller?.abort();
      loading.value = false;
    }
  }
  if (loading.value || done.value) return;

  const myGen = generation;
  controller?.abort();
  controller = new AbortController();
  loading.value = true;

  try {
    const page = await searchTitles(
      {
        q: trimmed || undefined,
        genres: selectedGenres.value.length ? selectedGenres.value : undefined,
        sort: sort.value,
        cursor,
        limit: PAGE_SIZE,
      },
      controller.signal,
    );
    if (myGen !== generation) return; // stale result
    items.value.push(...page.items);
    cursor = page.nextCursor ?? undefined;
    done.value = !page.nextCursor;
  } catch (e) {
    if (myGen === generation && (e as Error).name !== 'AbortError') {
      error.value = e instanceof Error ? e.message : 'Помилка пошуку';
    }
  } finally {
    if (myGen === generation) loading.value = false;
  }
}

function scheduleSearch(): void {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(() => {
    router.replace({ query: q.value.trim() ? { q: q.value.trim() } : {} });
    void runSearch(true);
  }, SEARCH_DEBOUNCE_MS);
}

function toggleGenre(id: number): void {
  const idx = selectedGenres.value.indexOf(id);
  if (idx >= 0) selectedGenres.value.splice(idx, 1);
  else selectedGenres.value.push(id);
  void runSearch(true);
}

function setSort(key: SortKey): void {
  sort.value = key;
  void runSearch(true);
}

watch(q, scheduleSearch);

watch(
  () => route.query.q,
  (newQ) => {
    const val = typeof newQ === 'string' ? newQ : '';
    if (q.value !== val) {
      q.value = val;
      void runSearch(true);
    }
  },
);

useIntersection(sentinel, () => void runSearch(false));

onMounted(async () => {
  genres.value = await fetchGenres().catch(() => []);
  void runSearch(true);
});
</script>

<template>
  <div class="search">
    <div class="search__bar">
      <input
        v-model="q"
        class="search__input"
        type="search"
        placeholder="Назва аніме…"
        aria-label="Пошук"
        autofocus
      />
    </div>

    <div class="search__sorts no-scrollbar">
      <button
        v-for="s in SORTS"
        :key="s.key"
        class="chip"
        :class="{ 'chip--active': sort === s.key }"
        type="button"
        @click="setSort(s.key)"
      >
        {{ s.label }}
      </button>
    </div>

    <div v-if="genres.length" class="search__genres no-scrollbar">
      <button
        v-for="g in genres"
        :key="g.id"
        class="chip chip--genre"
        :class="{ 'chip--active': selectedGenres.includes(g.id) }"
        type="button"
        @click="toggleGenre(g.id)"
      >
        {{ g.name }}
      </button>
    </div>

    <p v-if="tooShort" class="search__hint mono">
      Введіть щонайменше {{ MIN_QUERY_LENGTH }} символи
    </p>

    <div class="grid">
      <TitleCard v-for="t in items" :key="t.id" :title="t" />
      <template v-if="loading">
        <div v-for="n in 6" :key="`sk-${n}`" class="grid__sk">
          <BasePoster :src="null" />
          <BaseSkeleton height="0.8rem" width="80%" />
        </div>
      </template>
    </div>

    <p v-if="error" class="search__state">{{ error }}</p>
    <p v-else-if="done && !loading && items.length === 0 && !tooShort" class="search__state">
      Нічого не знайдено
    </p>
    <div ref="sentinel" class="grid__sentinel" />
  </div>
</template>

